private var lastRxAt = 0L   // elapsedRealtime : dernier signe de vie de `ws`
// connect(): right after `ws = client.newWebSocket(...)` -> lastRxAt = SystemClock.elapsedRealtime()
// onSocketMessage(): first line -> same
// Réseau revenu / écran rallumé : sans attendre le backoff ni le heartbeat
// (timers Handler gelés en veille profonde).
private fun kick() {
    if (Hub.service !== this || Prefs.paused) return   // service déjà détruit
    if (ws == null || SystemClock.elapsedRealtime() - lastRxAt > HEARTBEAT_TIMEOUT_MS) {
        attempts = 0
        connect()
    }
}
private val netCallback = object : ConnectivityManager.NetworkCallback() {
    override fun onAvailable(network: Network) { Hub.main.post { kick() } }
}
private val screenOn = object : BroadcastReceiver() {
    override fun onReceive(c: Context, i: Intent) { kick() }
}
onCreate, after connect(): runCatching { getSystemService(ConnectivityManager::class.java).registerDefaultNetworkCallback(netCallback) }; registerReceiver(screenOn, IntentFilter(Intent.ACTION_SCREEN_ON))
onDestroy, first lines: runCatching { ...unregisterNetworkCallback(netCallback) }; runCatching { unregisterReceiver(screenOn) }
