private val TIME_RE = Regex("^(\\d{1,2}):(\\d{2})$")   // Pattern est thread-safe
private fun toMinutes(s: String): Int? {
    val m = TIME_RE.find(s) ?: return null
    return m.groupValues[1].toInt() * 60 + m.groupValues[2].toInt()
}
